const CANCEL_STRIDE = 16;
const PROTOTYPE_KEYS = ["__proto__", "constructor", "prototype"] as const;

type DecodeCtx = {
  // "| undefined" is load-bearing under exactOptionalPropertyTypes: beginDecode
  // builds this from options?.signal, which is AbortSignal | undefined.
  signal?: AbortSignal | undefined;
  nodes: number;
  maxBytes: number;
};

function fail(code: DecodeErrorCode, path: string, message: string): never {
  throw new DecodeError(code, path, message);
}

function checkCancel(ctx: DecodeCtx): void {
  if (ctx.signal?.aborted) {
    fail("cancelled", "", "decode cancelled");
  }
}

function visit(ctx: DecodeCtx): void {
  ctx.nodes += 1;
  if (ctx.nodes > MAX_JSON_NODES) {
    fail("oversized", "", "JSON node bound exceeded");
  }
  if (ctx.nodes % CANCEL_STRIDE === 0) {
    checkCancel(ctx);
  }
}

function isObject(value: unknown): value is { [key: string]: unknown } {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function isPrototypeKey(key: string): boolean {
  return (PROTOTYPE_KEYS as readonly string[]).includes(key);
}

function asciiLowercase(name: string): string {
  let out = "";
  for (let index = 0; index < name.length; index += 1) {
    const code = name.charCodeAt(index);
    out += code >= 65 && code <= 90 ? String.fromCharCode(code + 32) : name[index];
  }
  return out;
}

function isDeniedArgumentName(name: string): boolean {
  const names = DENIED_ARGUMENT_NAMES as readonly string[];
  if (names.includes(name)) {
    return true;
  }
  const lower = asciiLowercase(name);
  return lower !== name && names.includes(lower);
}

function rejectPrototypeKey(key: string, path: string): void {
  if (isPrototypeKey(key)) {
    fail("malformed", path, "prototype-polluting key");
  }
}

function emptyObject<T extends { [key: string]: unknown }>(): T {
  return Object.create(null) as T;
}

function expectObject(value: unknown, path: string): { [key: string]: unknown } {
  if (!isObject(value)) {
    fail("invalid_type", path, "expected object");
  }
  const out = emptyObject<{ [key: string]: unknown }>();
  for (const key of Object.keys(value)) {
    const childPath = path === "" ? key : `${path}.${key}`;
    rejectPrototypeKey(key, childPath);
    out[key] = value[key];
  }
  return out;
}

function expectField(
  obj: { [key: string]: unknown },
  key: string,
  path: string,
): unknown {
  if (!Object.prototype.hasOwnProperty.call(obj, key)) {
    fail("missing_field", path === "" ? key : `${path}.${key}`, `missing field ${key}`);
  }
  return obj[key];
}

function rejectUnknownFields(
  obj: { [key: string]: unknown },
  allowed: readonly string[],
  path: string,
): void {
  for (const key of Object.keys(obj)) {
    if (!allowed.includes(key)) {
      fail("malformed", path === "" ? key : `${path}.${key}`, `unknown field ${key}`);
    }
  }
}

function asString(value: unknown, path: string, maxBytes: number): string {
  if (typeof value !== "string") {
    fail("invalid_type", path, "expected string");
  }
  if (Buffer.byteLength(value, "utf8") > maxBytes) {
    fail("oversized", path, "string exceeds byte bound");
  }
  return value;
}

function asNonEmptyString(value: unknown, path: string, maxBytes: number): string {
  const text = asString(value, path, maxBytes);
  if (text.length === 0) {
    fail("malformed", path, "string must be non-empty");
  }
  return text;
}

function asUuid(value: unknown, path: string): Uuid {
  const text = asString(value, path, 36);
  if (!UUID_PATTERN.test(text)) {
    fail("malformed", path, "expected lowercase hyphenated UUID");
  }
  return text;
}

function asArtifactId(value: unknown, path: string): ArtifactId {
  const text = asString(value, path, 71);
  if (!ARTIFACT_ID_PATTERN.test(text)) {
    fail("malformed", path, "expected sha256:<64 lowercase hex>");
  }
  return text;
}

function asUint(value: unknown, path: string): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
    fail("invalid_type", path, "expected unsigned integer");
  }
  if (value > Number.MAX_SAFE_INTEGER) {
    fail("oversized", path, "integer exceeds safe bound");
  }
  return value;
}

function asBoolean(value: unknown, path: string): boolean {
  if (typeof value !== "boolean") {
    fail("invalid_type", path, "expected boolean");
  }
  return value;
}

function asClosed<T extends string>(
  value: unknown,
  allowed: readonly T[],
  path: string,
): T {
  if (typeof value !== "string" || !allowed.includes(value as T)) {
    fail("unknown_variant", path, "unknown closed enum variant");
  }
  return value as T;
}

function asOptionalNull<T>(
  value: unknown,
  path: string,
  decode: (inner: unknown, innerPath: string) => T,
): T | null {
  if (value === undefined || value === null) {
    return null;
  }
  return decode(value, path);
}

function asRecordedAt(value: unknown, path: string): string {
  const text = asString(value, path, 40);
  if (text.length < 20) {
    fail("malformed", path, "malformed recorded_at timestamp");
  }
  const prefix = text.slice(0, 19);
  if (
    prefix.length !== 19 ||
    prefix[4] !== "-" ||
    prefix[7] !== "-" ||
    prefix[10] !== "T" ||
    prefix[13] !== ":" ||
    prefix[16] !== ":"
  ) {
    fail("malformed", path, "malformed recorded_at timestamp");
  }
  for (const index of [0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18]) {
    const code = prefix.charCodeAt(index);
    if (code < 48 || code > 57) {
      fail("malformed", path, "malformed recorded_at timestamp");
    }
  }
  const rest = text.slice(19);
  if (rest === "Z" || rest === "+00:00") {
    return rest === "+00:00" ? `${prefix}Z` : text;
  }
  if (rest.startsWith(".") && rest.endsWith("Z")) {
    const digits = rest.slice(1, -1);
    if (
      digits.length === 0 ||
      digits.length > 9 ||
      !/^[0-9]+$/.test(digits)
    ) {
      fail("malformed", path, "malformed recorded_at timestamp");
    }
    return text;
  }
  fail("malformed", path, "malformed recorded_at timestamp");
}

function accountStringBytes(text: string, path: string, ctx: DecodeCtx): void {
  if (Buffer.byteLength(text, "utf8") > ctx.maxBytes) {
    fail("oversized", path, "string exceeds byte bound");
  }
}

function decodeJsonValue(value: unknown, path: string, ctx: DecodeCtx, depth: number): JsonValue {
  visit(ctx);
  if (depth > MAX_JSON_DEPTH) {
    fail("oversized", path, "JSON depth bound exceeded");
  }
  if (value === null || typeof value === "boolean") {
    return value;
  }
  if (typeof value === "string") {
    accountStringBytes(value, path, ctx);
    return value;
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      fail("malformed", path, "non-finite number");
    }
    return value;
  }
  if (Array.isArray(value)) {
    return value.map((item, index) =>
      decodeJsonValue(item, `${path}[${index}]`, ctx, depth + 1),
    );
  }
  if (isObject(value)) {
    const out = emptyObject<JsonObject>();
    for (const key of Object.keys(value)) {
      const childPath = path === "" ? key : `${path}.${key}`;
      rejectPrototypeKey(key, childPath);
      accountStringBytes(key, childPath, ctx);
      out[key] = decodeJsonValue(value[key], childPath, ctx, depth + 1);
    }
    return out;
  }
  fail("invalid_type", path, "expected JSON value");
}

function decodeActor(value: unknown, path: string, ctx: DecodeCtx): ActorRef {
  visit(ctx);
  const obj = expectObject(value, path);
  rejectUnknownFields(obj, ["kind", "id", "org_id", "device_id"], path);
  const actor: ActorRef = {
    kind: asClosed(expectField(obj, "kind", path), ACTOR_KINDS, `${path}.kind`),
    id: asNonEmptyString(expectField(obj, "id", path), `${path}.id`, MAX_ACTOR_ATTR_BYTES),
  };
  if (obj.org_id !== undefined) {
    actor.org_id = asNonEmptyString(obj.org_id, `${path}.org_id`, MAX_ACTOR_ATTR_BYTES);
  }
  if (obj.device_id !== undefined) {
    actor.device_id = asNonEmptyString(obj.device_id, `${path}.device_id`, MAX_ACTOR_ATTR_BYTES);
  }
  return actor;
}

function decodeArtifactRef(value: unknown, path: string, ctx: DecodeCtx): ArtifactRef {
  visit(ctx);
  const obj = expectObject(value, path);
  rejectUnknownFields(obj, ["id", "media_type", "bytes", "redaction"], path);
  return {
    id: asArtifactId(expectField(obj, "id", path), `${path}.id`),
    media_type: asNonEmptyString(
      expectField(obj, "media_type", path),
      `${path}.media_type`,
      256,
    ),
    bytes: asUint(expectField(obj, "bytes", path), `${path}.bytes`),
    redaction: asClosed(
      expectField(obj, "redaction", path),
      REDACTION_CLASSES,
      `${path}.redaction`,
    ),
  };
}

function decodeDetails(value: unknown, path: string, ctx: DecodeCtx): ErrorDetails {
  visit(ctx);
  const obj = expectObject(value, path);
  const keys = Object.keys(obj);
  if (keys.length > MAX_DETAIL_FIELDS) {
    fail("oversized", path, "error details exceed the field bound");
  }
  const details = emptyObject<ErrorDetails>();
  for (const key of keys) {
    if (key.length === 0) {
      fail("malformed", path, "error details key must be non-empty");
    }
    if (Buffer.byteLength(key, "utf8") > MAX_DETAIL_KEY_BYTES) {
      fail("oversized", `${path}.${key}`, "error details key exceeds the byte bound");
    }
    if (RESERVED_DETAIL_KEYS.includes(key.toLowerCase() as (typeof RESERVED_DETAIL_KEYS)[number])) {
      fail("reserved_field", `${path}.${key}`, "error details key is reserved");
    }
    const item = obj[key];
    if (typeof item !== "string") {
      fail("invalid_type", `${path}.${key}`, "error details values must be strings");
    }
    if (Buffer.byteLength(item, "utf8") > MAX_DETAIL_VALUE_BYTES) {
      fail("oversized", `${path}.${key}`, "error details value exceeds the byte bound");
    }
    details[key] = item;
  }
  return details;
}

function decodeCriterion(value: unknown, path: string, ctx: DecodeCtx): Criterion {
  visit(ctx);
  const obj = expectObject(value, path);
  rejectUnknownFields(obj, ["id", "text"], path);
  return {
    id: asNonEmptyString(expectField(obj, "id", path), `${path}.id`, MAX_CRITERION_TEXT_BYTES),
    text: asNonEmptyString(expectField(obj, "text", path), `${path}.text`, MAX_CRITERION_TEXT_BYTES),
  };
}

function decodeEvidenceRequirement(
  value: unknown,
  path: string,
  ctx: DecodeCtx,
): EvidenceRequirement {
  visit(ctx);
  const obj = expectObject(value, path);
  rejectUnknownFields(obj, ["criterion_id", "kinds"], path);
  const kindsValue = expectField(obj, "kinds", path);
  if (!Array.isArray(kindsValue)) {
    fail("invalid_type", `${path}.kinds`, "expected array");
  }
  if (kindsValue.length > MAX_EVIDENCE_KINDS) {
    fail("oversized", `${path}.kinds`, "too many evidence kinds");
  }
  return {
    criterion_id: asNonEmptyString(
      expectField(obj, "criterion_id", path),
      `${path}.criterion_id`,
      MAX_CRITERION_TEXT_BYTES,
    ),
    kinds: kindsValue.map((kind, index) =>
      asNonEmptyString(kind, `${path}.kinds[${index}]`, MAX_CRITERION_TEXT_BYTES),
    ),
  };
}

function decodeCriteria(value: unknown, path: string, ctx: DecodeCtx): Criterion[] {
  if (!Array.isArray(value)) {
    fail("invalid_type", path, "expected array");
  }
  if (value.length > MAX_CRITERIA) {
    fail("oversized", path, "too many completion criteria");
  }
  return value.map((item, index) => decodeCriterion(item, `${path}[${index}]`, ctx));
}

function decodeEvidenceRequirements(
  value: unknown,
  path: string,
  ctx: DecodeCtx,
): EvidenceRequirement[] {
  if (!Array.isArray(value)) {
    fail("invalid_type", path, "expected array");
  }
  if (value.length > MAX_EVIDENCE_REQUIREMENTS) {
    fail("oversized", path, "too many evidence requirements");
  }
  return value.map((item, index) =>
    decodeEvidenceRequirement(item, `${path}[${index}]`, ctx),
  );
}

function optionalUintField(
  obj: { [key: string]: unknown },
  key: string,
  path: string,
): number | null {
  if (!Object.prototype.hasOwnProperty.call(obj, key) || obj[key] === null) {
    return null;
  }
  return asUint(obj[key], `${path}.${key}`);
}

export function decodeApiError(input: unknown, options?: DecodeOptions): ApiError {
  const ctx = beginDecode(input, options);
  const obj = expectObject(input, "");
  rejectUnknownFields(obj, ["code", "message", "retryable", "trace_id", "details"], "");
  const code = asClosed(expectField(obj, "code", ""), ERROR_CODES, "code");
  const retryable = asBoolean(expectField(obj, "retryable", ""), "retryable");
  if (retryable !== ERROR_RETRYABLE[code]) {
    fail("malformed", "retryable", "retryable does not match error code");
  }
  return {
    code,
    message: asNonEmptyString(expectField(obj, "message", ""), "message", MAX_MESSAGE_BYTES),
    retryable,
    trace_id: asUuid(expectField(obj, "trace_id", ""), "trace_id"),
    details: decodeDetails(expectField(obj, "details", ""), "details", ctx),
  } as ApiError;
}

export const decodeError = decodeApiError;

function encodeJsonValue(value: JsonValue): JsonValue {
  if (value === null || typeof value !== "object") {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map((item) => encodeJsonValue(item));
  }
  const out: JsonObject = {};
  for (const key of Object.keys(value)) {
    const child = value[key];
    if (child !== undefined) {
      out[key] = encodeJsonValue(child);
    }
  }
  return out;
}

function encodeDetails(details: ErrorDetails): ErrorDetails {
  const out: ErrorDetails = {};
  for (const key of Object.keys(details)) {
    const child = details[key];
    if (child !== undefined) {
      out[key] = child;
    }
  }
  return out;
}

export function encodeApiError(value: ApiError): ApiError {
  return {
    code: value.code,
    message: value.message,
    retryable: value.retryable,
    trace_id: value.trace_id,
    details: encodeDetails(value.details),
  } as ApiError;
}

export const encodeError = encodeApiError;

