export function decodeToolResult(input: unknown, options?: DecodeOptions): ToolResultRecord {
  const ctx = beginDecode(input, options);
  const obj = expectObject(input, "");
  rejectUnknownFields(
    obj,
    [
      "schema",
      "call_id",
      "status",
      "summary",
      "data",
      "artifacts",
      "truncated",
      "continuation",
    ],
    "",
  );
  const schema = asUint(expectField(obj, "schema", ""), "schema");
  if (schema !== TOOL_RESULT_SCHEMA) {
    fail("unsupported_schema", "schema", `unsupported tool result schema ${schema}`);
  }
  const artifactsValue = expectField(obj, "artifacts", "");
  if (!Array.isArray(artifactsValue)) {
    fail("invalid_type", "artifacts", "expected array");
  }
  if (artifactsValue.length > MAX_ARTIFACTS) {
    fail("oversized", "artifacts", "too many artifacts");
  }
  return {
    schema: TOOL_RESULT_SCHEMA,
    call_id: asNonEmptyString(expectField(obj, "call_id", ""), "call_id", MAX_CALL_ID_BYTES),
    status: asClosed(expectField(obj, "status", ""), TOOL_RESULT_STATUSES, "status"),
    summary: asString(expectField(obj, "summary", ""), "summary", MAX_SUMMARY_BYTES),
    data: decodeJsonValue(expectField(obj, "data", ""), "data", ctx, 0),
    artifacts: artifactsValue.map((item, index) =>
      decodeArtifactRef(item, `artifacts[${index}]`, ctx),
    ),
    truncated: asBoolean(expectField(obj, "truncated", ""), "truncated"),
    continuation: asOptionalNull(obj.continuation, "continuation", (inner, path) => {
      const cont = expectObject(inner, path);
      rejectUnknownFields(cont, ["artifact_id"], path);
      return {
        artifact_id: asArtifactId(expectField(cont, "artifact_id", path), `${path}.artifact_id`),
      };
    }),
  };
}

export function encodeToolResult(value: ToolResultRecord): ToolResultRecord {
  return {
    schema: TOOL_RESULT_SCHEMA,
    call_id: value.call_id,
    status: value.status,
    summary: value.summary,
    data: encodeJsonValue(value.data),
    artifacts: value.artifacts.map((item) => ({ ...item })),
    truncated: value.truncated,
    continuation: value.continuation === null ? null : { ...value.continuation },
  };
}

export function decodeArtifact(input: unknown, options?: DecodeOptions): ArtifactRef {
  const ctx = beginDecode(input, options);
  return decodeArtifactRef(input, "", ctx);
}

export function encodeArtifact(value: ArtifactRef): ArtifactRef {
  return {
    id: value.id,
    media_type: value.media_type,
    bytes: value.bytes,
    redaction: value.redaction,
  };
}

export function parseJson(
  text: string,
  options?: DecodeOptions & { maxBytes?: number },
): unknown {
  const maxBytes = options?.maxBytes ?? MAX_DECODE_BYTES;
  if (Buffer.byteLength(text, "utf8") > maxBytes) {
    fail("oversized", "", "JSON text exceeds byte bound");
  }
  if (options?.signal?.aborted) {
    fail("cancelled", "", "decode cancelled");
  }
  try {
    return JSON.parse(text);
  } catch {
    fail("malformed", "", "JSON text is not valid");
  }
}

function encodedJsonBytes(value: unknown): number {
  let encoded: string;
  try {
    encoded = JSON.stringify(value) as string;
  } catch {
    fail("malformed", "", "value is not JSON-serializable");
  }
  if (typeof encoded !== "string") {
    fail("invalid_type", "", "value is not JSON-serializable");
  }
  return Buffer.byteLength(encoded, "utf8");
}

function beginDecode(
  input: unknown,
  options?: DecodeOptions,
  defaultMax: number = MAX_DECODE_BYTES,
): DecodeCtx {
  if (options?.signal?.aborted) {
    fail("cancelled", "", "decode cancelled");
  }
  const maxBytes = options?.maxBytes ?? defaultMax;
  if (
    typeof maxBytes !== "number" ||
    !Number.isFinite(maxBytes) ||
    maxBytes < 0 ||
    maxBytes > Number.MAX_SAFE_INTEGER
  ) {
    fail("oversized", "", "invalid decode byte bound");
  }
  if (encodedJsonBytes(input) > maxBytes) {
    fail("oversized", "", "value exceeds decode byte bound");
  }
  return { signal: options?.signal, nodes: 0, maxBytes };
}

export function eventFamily(kind: EventKind): EventFamily {
  return EVENT_FAMILY_BY_KIND[kind];
}

